// Independent host-only physical oracle. No native or Julia GPU routine called.
#include "study_params.h"
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <cstdio>
#include <algorithm>
static double field(double x,double y,int seed){int ix=int(x),iy=int(y);double u=x-ix,v=y-iy;auto s=[](double t){double t2=t*t,t3=t2*t,t4=t2*t2,t5=t4*t;return 6*t5-15*t4+10*t3;};double sx=s(u),sy=s(v),q=std::sqrt(.5);double gx[]={1,-1,0,0,q,-q,q,-q},gy[]={0,0,1,-1,q,q,-q,-q};double sum=0;for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){int k=(PHASH[(PHASH[(ix+dx)&255]+((iy+dy)&255))&255]+seed)%8;sum+=(dx?sx:1-sx)*(dy?sy:1-sy)*(gx[k]*(u-dx)+gy[k]*(v-dy));}return .5+.5*sum;}
static std::vector<uint8_t> generate(int id){auto z=CASES[id];std::vector<uint8_t> out(pixels(id));for(int y=0;y<z.height;y++)for(int x=0;x<PW;x++){double total=0,norm=0,amplitude=1,freq=1;for(int o=0;o<z.octaves;o++){total+=amplitude*field(double(x)/z.ppu*freq,double(y)/z.ppu*freq,z.seed);norm+=amplitude;amplitude*=z.persistence;freq*=z.lac;}double v=255*total/norm;if(!(v>=0&&v<=255))throw std::runtime_error("physical noise range");out[uint64_t(y)*PW+x]=uint8_t(v);}return out;}
static const std::vector<uint8_t>&oracle(int c){static auto standard=generate(0),lattice=generate(6),seeded=generate(7);return c<6?standard:c==6?lattice:seeded;}
static void require(bool ok,const char*msg){if(!ok)throw std::runtime_error(msg);}
extern "C" int perlin_check(const char*path,double*ae,double*re){void*map=MAP_FAILED;int fd=-1;try{*ae=*re=0;fd=open(path,O_RDONLY);require(fd>=0,"open artifact");struct stat st;fstat(fd,&st);require(uint64_t(st.st_size)==ARTIFACT,"artifact length");map=mmap(nullptr,st.st_size,PROT_READ,MAP_PRIVATE,fd,0);require(map!=MAP_FAILED,"map artifact");auto a=static_cast<const uint8_t*>(map);auto constants=expected_constants();uint64_t pre=0,post=PREFIX;const uint8_t*standard=nullptr;
for(int c=0;c<8;c++){uint64_t bytes=pixels(c)*4;auto params=expected_params(c);for(int stage=0;stage<2;stage++){uint64_t&pos=stage?post:pre;require(!std::memcmp(a+pos,constants.data(),1088),"actual device hash/gradients");pos+=1088;const uint8_t*p=a+pos;for(int i=0;i<PG;i++)require(p[i]==173&&p[PG+36+i]==173,"parameter guard");require(!std::memcmp(p+PG,params.data(),36),"actual GPU scalar parameters");pos+=36+2*PG;p=a+pos;for(int i=0;i<PG;i++)require(p[i]==173&&p[PG+bytes+i]==173,"output guard");const uint8_t*data=p+PG;if(!stage){for(uint64_t i=0;i<bytes;i++)require(data[i]==17,"actual initial GPU output");}else{auto&o=oracle(c);for(uint64_t i=0;i<pixels(c);i++){int got=data[4*i];require(got==data[4*i+1]&&got==data[4*i+2]&&data[4*i+3]==255,"RGB/alpha identities");int e=std::abs(got-int(o[i]));*ae=std::max(*ae,double(e));*re=std::max(*re,double(e)/std::max(int(o[i]),1));require(e<=1,"full Float64 noise quantization oracle");if(c==6)require(got==127,"integer lattice closed form");int x=i%PW,y=i/PW;if(c<6&&x%250==0&&y%250==0)require(got==127,"default lattice intersections");}if(c==0)standard=data;else if(c<6)require(!std::memcmp(data,standard,bytes),"all six stream counts exact same field");}pos+=bytes+2*PG;}}
require(pre==PREFIX&&post==ARTIFACT,"layout consumed");munmap(map,st.st_size);close(fd);return 1;}catch(const std::exception&e){fprintf(stderr,"PERLIN_INDEPENDENT_CHECK %s\n",e.what());if(map!=MAP_FAILED)munmap(map,ARTIFACT);if(fd>=0)close(fd);return 0;}}
